import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Elementwise addition custom CUDA ----------
elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)
elementwise_add_source = """
__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Depthwise 2D convolution custom CUDA ----------
depthwise_conv_cpp_source = (
    "torch::Tensor depthwise_conv_cuda(torch::Tensor x);"
)
depthwise_conv_source = """
__global__ void depthwise_conv_kernel(const float* input, const float* kernel, float* output, int B, int C, int H, int W, int S, int P, int D, int Kh, int Kw) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * C * H * W) {
        int b = idx / (C * H * W);
        int rem = idx % (C * H * W);
        int c = rem / (H * W);
        rem = rem % (H * W);
        int oh = rem / W;
        int ow = rem % W;

        float sum = 0.0f;
        for (int kh = 0; kh < Kh; ++kh) {
            for (int kw = 0; kw < Kw; ++kw) {
                int ih = oh * S * Kh + kh + P;
                int iw = ow * S * Kw + kw + P;
                if (ih >= 0 && ih < H + 2*P - Kh*D + 1 && iw >= 0 && iw < W + 2*P - Kw*D + 1) {
                    int input_idx = ((b * C + c) * H * W + ih * W + iw);
                    sum += input[input_idx] * kernel[kh * Kw + kw];
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor depthwise_conv_cuda(torch::Tensor x) {
    # Placeholder: return zero tensor of same shape.
    auto out = torch.zeros_like(x);
    return out;
}
"""

depthwise_conv = load_inline(
    name="depthwise_conv",
    cpp_sources=depthwise_conv_cpp_source,
    cuda_sources=depthwise_conv_source,
    functions=["depthwise_conv_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Optimized Model ----------
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.elementwise_add = elementwise_add
        self.depthwise_conv = depthwise_conv

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = self.depthwise_conv(x)
        return out
